import app from 'flarum/admin/app';
import Modal from 'flarum/common/components/Modal';
import LoadingIndicator from 'flarum/common/components/LoadingIndicator';
import apiUrl from '../apiUrl';
/**
 * What an update gives you: every GitHub release between the installed
 * version and the one on offer, fetched by the server when this opens.
 */
export default class ReleaseNotesModal extends Modal {
  loading = true;
  releases = [];
  url = null;
  failed = false;
  oninit(vnode) {
    super.oninit(vnode);
    app.request({
      method: 'GET',
      url: apiUrl() + '/extension-manager/release-notes',
      params: {
        package: this.attrs.package
      }
    }).then(data => {
      this.releases = data.releases || [];
      this.url = data.url || null;
    }).catch(() => this.failed = true).finally(() => {
      this.loading = false;
      m.redraw();
    });
  }
  className() {
    return 'Modal--large ExtensionManager-notesModal';
  }
  title() {
    return app.translator.trans('flarum-extension-manager.admin.release_notes.title', {
      name: this.attrs.name,
      from: this.attrs.from,
      to: this.attrs.to
    });
  }
  content() {
    return m("div", {
      className: "Modal-body"
    }, this.body());
  }
  body() {
    if (this.loading) return m(LoadingIndicator, null);
    const link = this.url ? m("p", {
      className: "ExtensionManager-notesLink"
    }, m("a", {
      href: this.url,
      target: "_blank",
      rel: "noopener noreferrer"
    }, app.translator.trans('flarum-extension-manager.admin.release_notes.on_github'), ' ', m("i", {
      className: "fas fa-external-link-alt",
      "aria-hidden": "true"
    }))) : null;
    const releases = this.failed || this.releases.length === 0 ? m("p", null, this.failed ? app.translator.trans('flarum-extension-manager.admin.release_notes.failed') : app.translator.trans('flarum-extension-manager.admin.release_notes.none')) : m("div", {
      className: "ExtensionManager-releases"
    }, this.releases.map(r => m("section", {
      className: "ExtensionManager-release",
      key: r.tag
    }, m("h4", null, m("a", {
      href: r.url,
      target: "_blank",
      rel: "noopener noreferrer"
    }, r.name), r.publishedAt ? m("time", {
      dateTime: r.publishedAt
    }, new Date(r.publishedAt).toLocaleDateString()) : null), r.html ? m("div", {
      className: "ExtensionManager-releaseBody"
    }, m.trust(r.html)) : m("p", {
      className: "ExtensionManager-releaseEmpty"
    }, app.translator.trans('flarum-extension-manager.admin.release_notes.empty_release')))));
    return m("div", null, releases, link);
  }
}
flarum.reg.add('flarum-extension-manager', 'admin/components/ReleaseNotesModal', ReleaseNotesModal);